/** CI-only configuration and deny-only readiness recovery; never grants access or starts alarm/output runtime. */
public class AlarmProtectionFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private UiObject2 object(String description){UiObject2 value=device.wait(Until.findObject(By.desc(description)),5000);assertNotNull(description,value);return value;}
    private void click(String text)throws Exception{UiObject2 value=device.findObject(By.text(text));if(value==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(text));value=device.wait(Until.findObject(By.text(text)),5000);}assertNotNull(text,value);value.click();device.waitForIdle();}
    private void title(String text){assertTrue(text,device.wait(Until.hasObject(By.text(text)),5000));}
    private void later(){UiObject2 button=device.wait(Until.findObject(By.text(Pattern.compile("later",Pattern.CASE_INSENSITIVE))),5000);assertNotNull(button);button.click();device.waitForIdle();}
    private View focused(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()){assertNull("Exactly one focused application window",found);found=root;}return found;}
    private View find(View root,String value){if(root==null)return null;if(value.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View match=find(group.getChildAt(n),value);if(match!=null)return match;}return null;}
    private void awaitReadiness(BooleanSupplier condition,String label)throws Exception{long until=SystemClock.elapsedRealtime()+8000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(20);assertTrue(label,condition.getAsBoolean());}
    private View focused(String label)throws Exception{View[] root={null};awaitReadiness(()->{i.runOnMainSync(()->{View current=focused();root[0]=current!=null&&find(current,label)!=null?current:null;});return root[0]!=null;},"Focused native window contains "+label);return root[0];}
    private void frame(View root)throws Exception{CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Exact focused frame owner",root,focused());assertTrue(root.isHardwareAccelerated());root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue("Focused native frame committed",frame.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame(root,focused()));}
    private View action(View root,String label){View target=find(root,label);while(target!=null&&!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();return target;}
    private Rect whole(View target,String label){assertNotNull(label,target);assertTrue(label+" enabled action",target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(label+" visible",target.getGlobalVisibleRect(visible));assertEquals(label+" whole width",target.getWidth(),visible.width());assertEquals(label+" whole height",target.getHeight(),visible.height());assertTrue(label+"48dp width",visible.width()>=Design.dp(c,48));assertTrue(label+"48dp height",visible.height()>=Design.dp(c,48));int[] screen=new int[2];target.getLocationOnScreen(screen);return new Rect(screen[0],screen[1],screen[0]+target.getWidth(),screen[1]+target.getHeight());}
    private void tapReadiness(String label)throws Exception{View root=focused(label);awaitReadiness(()->{boolean[] yes={false};i.runOnMainSync(()->{if(focused()!=root)return;View target=action(root,label);if(target==null||!target.isEnabled())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),false);Rect visible=new Rect();yes[0]=target.getGlobalVisibleRect(visible)&&target.getWidth()==visible.width()&&target.getHeight()==visible.height();});return yes[0];},"Whole native input target "+label);frame(root);Rect[] bounds={null};i.runOnMainSync(()->{assertSame(root,focused());bounds[0]=whole(action(root,label),label);});assertTrue(label+" dispatched once",device.click(bounds[0].centerX(),bounds[0].centerY()));}
    private void capture(String name)throws Exception{View[] root={null};awaitReadiness(()->{i.runOnMainSync(()->root[0]=focused());return root[0]!=null;},"Focused capture "+name);frame(root[0]);File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"protection-"+name+".png")));}
    private void readinessState(MainActivity main,boolean whole)throws Exception{frame(focused("Alarm readiness"));i.runOnMainSync(()->{assertSame(main.getWindow().getDecorView(),focused());NotificationManager notifications=main.getSystemService(NotificationManager.class);Map<String,String> expected=new LinkedHashMap<>();expected.put("Exact alarms",main.getSystemService(AlarmManager.class).canScheduleExactAlarms()?"Allowed":"Needs attention");expected.put("Notifications",notifications.areNotificationsEnabled()?"Allowed":"Needs attention");expected.put("Full-screen alarms",notifications.canUseFullScreenIntent()?"Allowed":"Needs attention");expected.put("Background battery",main.getSystemService(PowerManager.class).isIgnoringBatteryOptimizations(main.getPackageName())?"Allowed":"Needs attention");expected.put("Microphone",main.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED?"Allowed":"Optional");for(Map.Entry<String,String> row:expected.entrySet()){View target=find(focused(),row.getKey()+" · "+row.getValue());assertNotNull("Rendered state matches current Android state: "+row.getKey(),target);if(whole)whole(target,row.getKey());}if(whole)whole(action(focused(),"Open battery settings"),"Battery settings action");});}
    private void denied(MainActivity main,boolean rationale)throws Exception{awaitReadiness(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=!main.isDestroyed()&&main.hasWindowFocus()&&focused()==main.getWindow().getDecorView()&&main.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_DENIED&&main.shouldShowRequestPermissionRationale(Manifest.permission.RECORD_AUDIO)==rationale);return yes[0];},"Denied microphone and rationale="+rationale+" on the owned Main window");}
    private int controllerWindow(String controller){android.view.accessibility.AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();if(root==null)return -1;try{if(!controller.equals(String.valueOf(root.getPackageName())))return -1;android.view.accessibility.AccessibilityWindowInfo window=root.getWindow();if(window==null)return -1;try{return window.isFocused()?window.getId():-1;}finally{window.recycle();}}finally{root.recycle();}}
    private void deny(String controller,String id)throws Exception{UiObject2 button=device.wait(Until.findObject(By.res(controller,id).enabled(true)),8000);assertNotNull("Exact OS denial resource "+controller+":id/"+id,button);awaitReadiness(()->controllerWindow(controller)>=0,"Permission-controller native input focus");assertEquals(controller,device.getCurrentPackageName());int owner=controllerWindow(controller);assertTrue("Focused permission-controller window ID",owner>=0);device.waitForIdle();button=device.findObject(By.res(controller,id).enabled(true));assertNotNull("Current exact OS denial action",button);Rect raw=device.findObject(new UiSelector().resourceId(controller+":id/"+id)).getBounds();Rect visible=button.getVisibleBounds();assertEquals("Whole OS denial target",raw,visible);assertTrue("Enabled OS denial target",button.isEnabled()&&button.isClickable());assertTrue("OS denial48dp width",visible.width()>=Design.dp(c,48));assertTrue("OS denial48dp height",visible.height()>=Design.dp(c,48));assertEquals("Exact focused OS owner before input",owner,controllerWindow(controller));assertTrue("One OS Deny tap",device.click(visible.centerX(),visible.centerY()));}
    private void readiness(Map<String,?> originalPreferences)throws Exception{
        final String asked="readinessMicrophoneAsked";MainActivity main=null;
        try{
            // Only disposable CI denial/user-fixed history changes; there are no Allow, grant or revoke calls.
            // The application request marker is restored below; the OS denial flags are intentionally not reset.
            assertEquals("Pinned readiness acceptance API",36,Build.VERSION.SDK_INT);assertEquals("Initial microphone grant remains denied",PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));assertFalse("Fresh CI permission request history",Prefs.flag(c,asked));
            android.content.pm.ResolveInfo controllerInfo=c.getPackageManager().resolveActivity(new Intent("android.content.pm.action.REQUEST_PERMISSIONS"),PackageManager.MATCH_SYSTEM_ONLY);assertNotNull("System handler of Android permission requests",controllerInfo);String controller=controllerInfo.activityInfo.packageName;
            main=(MainActivity)i.startActivitySync(new Intent(c,MainActivity.class).putExtra("destination",3).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));tapReadiness("Reliability");readinessState(main,true);capture("readiness");
            tapReadiness("Microphone");deny(controller,"permission_deny_button");denied(main,true);assertTrue(Prefs.flag(c,asked));tapReadiness("Microphone");View rationale=focused("Allow microphone access?");MainActivity owner=main;i.runOnMainSync(()->assertNotSame(owner.getWindow().getDecorView(),rationale));capture("readiness-rationale");tapReadiness("Not now");denied(main,true);assertFalse("Cancel does not reopen Android permission controller",device.hasObject(By.res(controller,"permission_message")));readinessState(main,false);capture("readiness-rationale-cancel");
            tapReadiness("Microphone");focused("Allow microphone access?");tapReadiness("Continue");deny(controller,"permission_deny_and_dont_ask_again_button");denied(main,false);focused("Used for sound events. Optional. Change access in app settings.");readinessState(main,false);capture("readiness-settings-recovery");
            Intent settings=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+c.getPackageName()));android.content.pm.ResolveInfo resolved=c.getPackageManager().resolveActivity(settings,PackageManager.MATCH_DEFAULT_ONLY);assertNotNull("System App info destination",resolved);String settingsPackage=resolved.activityInfo.packageName;String appLabel=c.getApplicationInfo().loadLabel(c.getPackageManager()).toString();tapReadiness("Microphone");assertTrue("Actual App info package",device.wait(Until.hasObject(By.pkg(settingsPackage).text(appLabel)),8000));assertEquals(settingsPackage,device.getCurrentPackageName());assertEquals("App info visit never grants microphone",PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));device.pressBack();denied(main,false);
            MainActivity previous=main;Instrumentation.ActivityMonitor monitor=i.addMonitor(MainActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);main=(MainActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull("Recreated readiness owner",main);}finally{i.removeMonitor(monitor);}awaitReadiness(previous::isDestroyed,"Old readiness Activity destroyed");denied(main,false);readinessState(main,false);focused("Used for sound events. Optional. Change access in app settings.");capture("readiness-returned");tapReadiness("Back");focused("Settings");assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));assertFalse(AlarmProtectionActivity.access(c));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"protection-readiness-failure.png"));device.dumpWindowHierarchy(new File(folder,"protection-readiness-failure.xml"));try(java.io.PrintWriter log=new java.io.PrintWriter(new File(folder,"protection-readiness-failure.txt"),"UTF-8")){log.println("Current package: "+device.getCurrentPackageName());failure.printStackTrace(log);}}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{SharedPreferences.Editor restore=Prefs.of(c).edit();if(originalPreferences.containsKey(asked)){assertTrue(originalPreferences.get(asked) instanceof Boolean);restore.putBoolean(asked,(Boolean)originalPreferences.get(asked));}else restore.remove(asked);assertTrue("Original readiness request marker restored",restore.commit());assertEquals("Readiness preserves every original shared preference",originalPreferences,Prefs.of(c).getAll());assertEquals("Readiness never grants microphone access",PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));}
    }
    @Test public void compactListAndGlobalProtectionsPersistWithoutAlarmExecution()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(Prefs.flag(c,"ringing"));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(AlarmProtectionActivity.access(c));
        String suffix=UUID.randomUUID().toString(),database="sleepwell-protection-"+suffix+".db",preferences="sleepwell-protection-"+suffix;
        SharedPreferences fixture=c.getSharedPreferences(preferences,Context.MODE_PRIVATE);Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());Records.Factory priorRecords=Records.factory;AlarmProtections.Factory priorSettings=AlarmProtections.factory;
        List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);assertFalse("An alarm must never be launched",a instanceof AlarmActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};
        app.registerActivityLifecycleCallbacks(lifecycle);
        try{
            Records.factory=context->new Store(context,database);AlarmProtections.factory=context->fixture;
            String saved;try(Store store=new Store(c,database)){Alarm first=new Alarm(1);first.hour=6;first.minute=30;first.label="Workdays";first.days.addAll(Set.of(1,2,3,4,5));first.enabled=true;store.save(first);Alarm second=new Alarm(2);second.hour=8;second.minute=30;second.label="Weekends";second.days.addAll(Set.of(6,7));second.enabled=true;store.save(second);saved=store.rows("SELECT * FROM alarms ORDER BY id").toString();}
            // Enabled rows are display-only fixtures. No scheduler method or toggle is invoked.
            c.startActivity(new Intent(c,MainActivity.class).putExtra("destination",1).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));object("Edit Workdays");assertTrue(object("Alarms").isSelected());assertFalse(device.hasObject(By.text("Smart wake-up")));assertFalse(device.hasObject(By.text("Challenges")));capture("alarms");
            object("Edit Workdays").click();title("Edit alarm");UiObject2 alarmOn=object("Alarm on");assertTrue(alarmOn.isChecked());assertTrue("Alarm on retains its 48dp target",alarmOn.getVisibleBounds().height()>=Math.round(48*c.getResources().getDisplayMetrics().density));assertTrue("Alarm on stays visible above Save",alarmOn.getVisibleBounds().bottom<=device.findObject(By.text("Save alarm")).getVisibleBounds().top);capture("editor");click("Alarm protection");title("Applies to all alarms");assertFalse(object("Prevent leaving app").isChecked());assertFalse(object("Prevent power off").isChecked());assertTrue(fixture.getAll().isEmpty());capture("off");
            object("Prevent leaving app").click();title("Enable the optional guard?");capture("disclosure");later();object("Prevent power off").click();title("Enable the optional guard?");later();assertTrue(object("Prevent power off").isChecked());assertTrue(object("Prevent leaving app").isChecked());capture("on");
            final Activity[] current={null};i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))current[0]=a;});assertTrue(current[0] instanceof AlarmProtectionActivity);Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmProtectionActivity.class.getName(),null,false);try{i.runOnMainSync(current[0]::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}title("Alarm protection");assertTrue(object("Prevent leaving app").isChecked());assertTrue(object("Prevent power off").isChecked());assertFalse(device.hasObject(By.text("Enable the optional guard?")));capture("recreated");
            click("Done");title("Save alarm");device.pressBack();object("Alarm options").click();title("Alarm options");click("Alarm protection");title("Alarm protection");assertTrue(object("Prevent power off").isChecked());capture("global");
            object("Prevent leaving app").click();assertFalse(object("Prevent leaving app").isChecked());assertTrue(object("Prevent power off").isChecked());capture("power-only");assertFalse(AlarmProtectionActivity.access(c));assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertEquals(personal,Prefs.of(c).getAll());try(Store store=new Store(c,database)){assertEquals(saved,store.rows("SELECT * FROM alarms ORDER BY id").toString());}
            readiness(personal);assertEquals(personal,Prefs.of(c).getAll());try(Store store=new Store(c,database)){assertEquals("Readiness never writes the fixture alarms",saved,store.rows("SELECT * FROM alarms ORDER BY id").toString());assertTrue("Readiness never records a session",store.rows("SELECT id FROM sessions").isEmpty());assertTrue("Readiness never captures sensor epochs",store.rows("SELECT id FROM epochs").isEmpty());}
        }finally{
            try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue("All owned Activities close before removing fixtures",owned.stream().allMatch(Activity::isDestroyed));HomeSurfaces.drain(8000);}
            finally{app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=priorRecords;AlarmProtections.factory=priorSettings;if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(database);c.deleteSharedPreferences(preferences);}}
        }
    }
}
